const items = $input.all();
if (!items || items.length === 0) return [];

const EMOJI = {
  seedling: "\u{1F331}", fire: "\u{1F525}", star: "\u{2B50}",
  warning: "\u{26A0}\u{FE0F}", calendar: "\u{1F4C5}",
  clipboard: "\u{1F4CB}", plant: "\u{1FAB4}", tada: "\u{1F389}"
};

const grouped = {};
for (const item of items) {
  const chatId = item.json.telegram_id;
  if (!chatId) continue;
  if (!grouped[chatId]) {
    grouped[chatId] = {
      chat_id: chatId,
      first_name: (item.json.full_name || "there").split(" ")[0],
      dueTasks: [],
      noDeadlineTasks: []
    };
  }
  const task = {
    id: item.json.task_id,
    description: item.json.description,
    deadline: item.json.deadline,
    priority: item.json.priority || "Medium"
  };
  if (!item.json.deadline) grouped[chatId].noDeadlineTasks.push(task);
  else grouped[chatId].dueTasks.push(task);
}

const output = [];
for (const chatId in grouped) {
  const user = grouped[chatId];
  if (user.dueTasks.length === 0 && user.noDeadlineTasks.length === 0) continue;

  let message = EMOJI.seedling + " *Good morning " + user.first_name + "!*\n\n";

  // Build compact button row: [✅1] [✅2] ... [•••]
  let buttons = [];
  let buttonRow = [];

  // Store task IDs for the More menu (comma-separated, max 5 tasks)
  const taskIds = user.dueTasks.slice(0, 5).map(t => t.id.substring(0, 8)).join(",");

  if (user.dueTasks.length > 0) {
    message += "Tasks due today:\n\n";
    user.dueTasks.forEach((task, i) => {
      const pEmoji = task.priority.toLowerCase() === "high" ? EMOJI.fire : EMOJI.star;
      message += (i+1) + ". " + pEmoji + " " + task.description + "\n";

      // Add numbered Done button (max 5)
      if (i < 5) {
        buttonRow.push({ text: "✅" + (i+1), callback_data: "d_" + task.id });
      }
    });

    // Add More menu button with task IDs
    buttonRow.push({ text: "•••", callback_data: "m_" + taskIds });
    buttons.push(buttonRow);
  } else {
    message += "No urgent tasks! " + EMOJI.tada + "\n";
  }

  if (user.noDeadlineTasks.length > 0) {
    message += "\n" + EMOJI.clipboard + " Backlog: " + user.noDeadlineTasks.length + " tasks";
  }

  message += "\n\n" + EMOJI.plant + " _Water your tasks!_";

  output.push({
    json: {
      chat_id: user.chat_id,
      message_text: message,
      reply_markup: JSON.stringify({ inline_keyboard: buttons }),
      task_ids: taskIds
    }
  });
}
return output;

// Parse the JSON string from Vision output
const parsed = JSON.parse($input.first().json['0'].content[0].text);
const data = parsed.extracted_data;

// Calculate end time if not provided
const calculateEndTime = (startTime) => {
  if (!startTime) return "22:00";
  const [hours, minutes] = startTime.split(':');
  const endHour = (parseInt(hours) + 3) % 24;
  return `${String(endHour).padStart(2, '0')}:${minutes}`;
};

const eventData = {
  summary: data.event_title || 'Untitled Event',
  start_datetime: `${data.event_date}T${data.event_time}:00+05:30`,
  end_datetime: `${data.event_date}T${data.event_end_time || calculateEndTime(data.event_time)}:00+05:30`,
  location: data.venue || '',
  description: `${data.notes || ''}\n\nHosts: ${data.hosts ? data.hosts.join(', ') : 'Unknown'}\n\nRSVP: ${data.rsvp_info || 'N/A'}\n\n---\nAdded via GrowFlow from Telegram`,
  color: '5',
  original_data: data
};

return { json: eventData };

